-- ============================================================================
-- B. ACCESS: containers (spine of the hierarchy), grants, sharing
-- ============================================================================

-- One registry row per space/folder/list. ASSUMED (our "single generic container" decision):
-- gives grants/locations/views a single FK target and holds the materialized path.
-- spaces/folders/lists below share this table's id (shared primary key).
CREATE TABLE containers (
  id              uuid PRIMARY KEY,
  workspace_id    uuid NOT NULL /* id -> access.workspaces */,
  kind            text NOT NULL CHECK (kind IN ('space','folder','list')),   -- PROVEN object types 4,5,6
  parent_id       uuid REFERENCES containers(id),      -- NULL for a space (its parent is the workspace)
  depth           smallint NOT NULL CHECK (depth BETWEEN 1 AND 3),
  ancestor_ids    uuid[] NOT NULL,                     -- root-first chain INCLUDING self; ASSUMED materialized path
  path            text NOT NULL COLLATE "C",           -- '/'-joined ids with trailing '/', for LIKE 'prefix%' subtree scans
  is_restricted   boolean NOT NULL DEFAULT false,      -- PROVEN "private" flag exists; inheritance semantic is ASSUMED
  status_set_id   uuid,                                -- EFFECTIVE status set (denormalized, always set); FK in Z. ASSUMED
  created_at      timestamptz NOT NULL DEFAULT now(),
  updated_at      timestamptz NOT NULL DEFAULT now(),
  version         integer NOT NULL DEFAULT 1,
  CHECK ((kind = 'space') = (parent_id IS NULL)),
  CHECK (ancestor_ids[array_length(ancestor_ids,1)] = id),
  CHECK (array_length(ancestor_ids,1) = depth)
);

CREATE INDEX containers_ws_parent_idx ON containers (workspace_id, parent_id);

-- children listing
CREATE INDEX containers_path_idx ON containers (workspace_id, path text_pattern_ops);

-- subtree scans (move, archive, search scope)
CREATE INDEX containers_ancestors_gin ON containers USING gin (ancestor_ids);

-- ============================================================================
-- C. HIERARCHY: spaces, folders, lists (typed extension of containers)
-- ============================================================================
-- Status sets are declared here because spaces/folders/lists point at nothing in them
-- directly; the effective set lives on containers.status_set_id.
CREATE TABLE status_templates (
  id            uuid PRIMARY KEY,
  workspace_id  uuid /* id -> access.workspaces */,        -- NULL = built-in template (the one exception: global seed rows). PROVEN 5 templates
  name          text NOT NULL,                         -- Kanban, Marketing, Content, Normal, Scrum
  created_at    timestamptz NOT NULL DEFAULT now(),
  updated_at    timestamptz NOT NULL DEFAULT now(),
  deleted_at    timestamptz,
  version       integer NOT NULL DEFAULT 1
);

CREATE INDEX status_templates_ws_idx ON status_templates (workspace_id) WHERE deleted_at IS NULL;

CREATE TABLE status_template_items (
  template_id   uuid NOT NULL REFERENCES status_templates(id) ON DELETE CASCADE,
  name          text NOT NULL,
  category      text NOT NULL CHECK (category IN ('open','custom','done','closed')),
  color         text,
  position      integer NOT NULL,
  PRIMARY KEY (template_id, name)
);

CREATE TABLE spaces (
  id            uuid PRIMARY KEY REFERENCES containers(id),
  workspace_id  uuid NOT NULL /* id -> access.workspaces */,
  name          text NOT NULL,                         -- PROVEN
  description   text,                                  -- PROVEN content
  color         text,                                  -- PROVEN
  avatar_source text,                                  -- PROVEN
  avatar_value  text,                                  -- PROVEN
  position      text NOT NULL COLLATE "C",             -- fractional index; PROVEN orderindex was int, string is ASSUMED
  owner_id      uuid /* id -> identity.users */,             -- PROVEN
  created_by    uuid /* id -> identity.users */,             -- PROVEN creator_id
  features      jsonb NOT NULL DEFAULT '{}',           -- ClickApps per space (PROVEN space settings exist; shape ASSUMED). Per-type config only
  archived_at   timestamptz,                           -- PROVEN archived flag; timestamp ASSUMED
  deleted_at    timestamptz,                           -- PROVEN
  deleted_by    uuid /* id -> identity.users */,
  created_at    timestamptz NOT NULL DEFAULT now(),
  updated_at    timestamptz NOT NULL DEFAULT now(),
  version       integer NOT NULL DEFAULT 1
);

CREATE INDEX spaces_ws_pos_idx ON spaces (workspace_id, position, id) WHERE deleted_at IS NULL;

-- sidebar order
CREATE UNIQUE INDEX spaces_ws_name_uk ON spaces (workspace_id, lower(name)) WHERE deleted_at IS NULL;

-- ASSUMED
CREATE TABLE folders (
  id            uuid PRIMARY KEY REFERENCES containers(id),
  workspace_id  uuid NOT NULL /* id -> access.workspaces */,
  space_id      uuid NOT NULL REFERENCES spaces(id),
  name          text NOT NULL,
  position      text NOT NULL COLLATE "C",
  created_by    uuid /* id -> identity.users */,
  archived_at   timestamptz,
  deleted_at    timestamptz,
  deleted_by    uuid /* id -> identity.users */,
  created_at    timestamptz NOT NULL DEFAULT now(),
  updated_at    timestamptz NOT NULL DEFAULT now(),
  version       integer NOT NULL DEFAULT 1
);

CREATE INDEX folders_space_pos_idx ON folders (workspace_id, space_id, position, id) WHERE deleted_at IS NULL;

CREATE INDEX folders_space_archived_idx ON folders (workspace_id, space_id) WHERE archived_at IS NOT NULL AND deleted_at IS NULL;

CREATE TABLE lists (
  id            uuid PRIMARY KEY REFERENCES containers(id),
  workspace_id  uuid NOT NULL /* id -> access.workspaces */,
  space_id      uuid NOT NULL REFERENCES spaces(id),
  folder_id     uuid REFERENCES folders(id),           -- NULL = folderless list directly in the space (PROVEN)
  name          text NOT NULL,
  description   text,
  color         text,
  position      text NOT NULL COLLATE "C",             -- order inside folder, or inside the space for folderless lists
  default_task_type_id uuid,                           -- ASSUMED; FK in Z
  start_at      timestamptz,                           -- PROVEN list start/due dates exist in ClickUp lists (as API fields), ASSUMED here
  due_at        timestamptz,
  created_by    uuid /* id -> identity.users */,
  archived_at   timestamptz,
  deleted_at    timestamptz,
  deleted_by    uuid /* id -> identity.users */,
  created_at    timestamptz NOT NULL DEFAULT now(),
  updated_at    timestamptz NOT NULL DEFAULT now(),
  version       integer NOT NULL DEFAULT 1
);

-- Lists of a folder in order.
CREATE INDEX lists_folder_pos_idx ON lists (workspace_id, folder_id, position, id) WHERE deleted_at IS NULL AND folder_id IS NOT NULL;

-- Folderless lists of a space in order.
CREATE INDEX lists_space_pos_idx ON lists (workspace_id, space_id, position, id) WHERE deleted_at IS NULL AND folder_id IS NULL;

CREATE INDEX lists_archived_idx ON lists (workspace_id, space_id) WHERE archived_at IS NOT NULL AND deleted_at IS NULL;

-- ============================================================================
-- D. STATUSES
-- ============================================================================
-- A status set belongs to ONE owning container (space/folder/list). A container without its own
-- set inherits its parent's; containers.status_set_id always holds the effective set. ASSUMED
-- (PROVEN: scope = space/folder/list, "inherit" vs "custom" choice, template choice).
CREATE TABLE status_sets (
  id                uuid PRIMARY KEY,
  workspace_id      uuid NOT NULL /* id -> access.workspaces */,
  owner_container_id uuid NOT NULL REFERENCES containers(id),
  template_id       uuid REFERENCES status_templates(id),
  progress_icons    boolean NOT NULL DEFAULT false,     -- PROVEN Status ClickApp
  created_at        timestamptz NOT NULL DEFAULT now(),
  updated_at        timestamptz NOT NULL DEFAULT now(),
  version           integer NOT NULL DEFAULT 1
);

CREATE UNIQUE INDEX status_sets_owner_uk ON status_sets (owner_container_id);

CREATE INDEX status_sets_ws_idx ON status_sets (workspace_id, id);

-- Categories open/custom/done/closed: PROVEN (type column and client enum). Reports key off category, never name. ASSUMED rule.
CREATE TABLE task_statuses (
  id               uuid PRIMARY KEY,
  workspace_id     uuid NOT NULL /* id -> access.workspaces */,
  status_set_id    uuid NOT NULL REFERENCES status_sets(id),
  name             text NOT NULL,                       -- PROVEN
  color            text,                                -- PROVEN
  category         text NOT NULL CHECK (category IN ('open','custom','done','closed')),
  position         text NOT NULL COLLATE "C",
  task_type_id     uuid,                                -- PROVEN custom_item_id (empty); FK in Z
  replaced_by_status_id uuid REFERENCES task_statuses(id), -- forced replacement target when removed. ASSUMED (removal never observed)
  deleted_at       timestamptz,
  created_at       timestamptz NOT NULL DEFAULT now(),
  updated_at       timestamptz NOT NULL DEFAULT now(),
  version          integer NOT NULL DEFAULT 1,
  CHECK (replaced_by_status_id IS NULL OR deleted_at IS NOT NULL),
  CHECK (replaced_by_status_id IS DISTINCT FROM id)
);

CREATE UNIQUE INDEX task_statuses_set_name_uk ON task_statuses (status_set_id, lower(name)) WHERE deleted_at IS NULL;

-- Status picker / board columns of a set in order.
CREATE INDEX task_statuses_set_pos_idx ON task_statuses (workspace_id, status_set_id, position) WHERE deleted_at IS NULL;

-- Find "the done statuses of a set" for progress and recurring logic.
CREATE INDEX task_statuses_set_cat_idx ON task_statuses (status_set_id, category) WHERE deleted_at IS NULL;

-- Optional workflow, empty = anything allowed. ASSUMED
CREATE TABLE status_transitions (
  workspace_id  uuid NOT NULL /* id -> access.workspaces */,
  status_set_id uuid NOT NULL REFERENCES status_sets(id) ON DELETE CASCADE,
  from_status_id uuid NOT NULL REFERENCES task_statuses(id),
  to_status_id  uuid NOT NULL REFERENCES task_statuses(id),
  PRIMARY KEY (status_set_id, from_status_id, to_status_id),
  CHECK (from_status_id <> to_status_id)
);

