-- FRD 'Review category' (5.4) and reviewer's 'In review'. Category stays open/custom/done/closed
CREATE TABLE status_required_fields (
  workspace_id uuid NOT NULL /* id -> access.workspaces */,
  status_id uuid NOT NULL REFERENCES task_statuses(id) ON DELETE CASCADE,
  custom_field_id uuid /* id -> tasks.custom_fields */,
